#![no_main]

//! Drives the rules-list grammar with raw text and with token-built lists.

/// Imports fuzz macro that repeatedly calls target closure with generated bytes.
use libfuzzer_sys::fuzz_target;

/// Imports the shared oracle and the token generator.
use forbidden_strings_fuzz::rules_list::{check_rules_list_value, generated_rules_list};

// What:     `fuzz_target!(|data: &[u8]| { ... })` declares the libFuzzer entry.
// Why:      The grammar must never panic, must agree with an independently written reference parse,
//           and a successful parse must render back to the exact input; raw UTF-8 reaches arbitrary bytes
//           and the token generator reaches the delimiter, marker, and duplicate branches with short inputs.
//
// In TS you'd write (pseudocode):
// ```ts
// for (const data of generatedInputs) { checkRulesListValue(decode(data)); checkRulesListValue(tokens(data)); }
// ```
fuzz_target!(|data: &[u8]| {
    if let Ok(text) = std::str::from_utf8(data) {
        check_rules_list_value(text);
    }
    check_rules_list_value(generated_rules_list(data).as_str());
});
